        :root {
            --primary: #3B82F6;
            --primary-dark: #2563EB;
            --text-main: #1F2937;
            --text-light: #6B7280;
            --bg-body: #F9FAFB;
            --bg-card: #FFFFFF;
            --border: #E5E7EB;
            --radius: 12px;
            --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
