        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; background-color: var(--bg-body); color: var(--text-main); line-height: 1.6; }
        a { text-decoration: none; color: inherit; transition: 0.2s; }
        ul { list-style: none; }
        img { max-width: 100%; display: block; }

        /* Layout */
        .container { max-width: 1100px; margin: 0 auto; padding: 0 20px; }
        .header { background: var(--bg-card); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; padding: 15px 0; }
        .nav-wrapper { display: flex; justify-content: space-between; align-items: center; }
        .logo { font-size: 24px; font-weight: 800; color: var(--primary); display: flex; align-items: center; gap: 8px; }
        .logo span { color: var(--text-main); }
        .nav-links { display: flex; gap: 30px; display: none; }
        .nav-links.active { display: flex; }
        .nav-item:hover { color: var(--primary); }
        .btn { padding: 10px 20px; border-radius: var(--radius); font-weight: 600; cursor: pointer; border: none; transition: 0.2s; display: inline-block; text-align: center;}
        .btn-primary { background: var(--primary); color: white; }
        .btn-primary:hover { background: var(--primary-dark); }
        .btn-outline { border: 1px solid var(--border); background: transparent; color: var(--text-main); }
        .btn-outline:hover { border-color: var(--primary); color: var(--primary); }

        /* Mobile Menu */
        .menu-toggle { display: none; font-size: 24px; cursor: pointer; }

        @media (min-width: 768px) {
            .nav-links { display: flex !important; }
            .menu-toggle { display: none; }
        }
        @media (max-width: 767px) {
            .menu-toggle { display: block; }
            .nav-links { position: absolute; top: 60px; left: 0; width: 100%; background: var(--bg-card); padding: 20px; border-bottom: 1px solid var(--border); display: none; flex-direction: column; gap: 15px; box-shadow: var(--shadow); }
            .nav-links.active { display: flex; }
        }

        /* Hero Section */
        .hero { padding: 60px 0; text-align: center; background: linear-gradient(135deg, #EFF6FF 0%, #FFFFFF 100%); border-bottom: 1px solid var(--border); }
        .hero h1 { font-size: 2.5rem; margin-bottom: 20px; color: var(--text-main); }
        .hero p { font-size: 1.1rem; color: var(--text-light); margin-bottom: 30px; max-width: 600px; margin-left: auto; margin-right: auto; }

        /* Feed Section */
        .main-content { padding: 40px 0; display: grid; grid-template-columns: 1fr; gap: 30px; }
        @media (min-width: 1024px) {
            .main-content { grid-template-columns: 2fr 1fr; }
        }

        .feed { display: flex; flex-direction: column; gap: 20px; }
        .post-card { background: var(--bg-card); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); }
        .post-header { display: flex; align-items: center; gap: 12px; margin-bottom: 15px; }
        .avatar { width: 40px; height: 40px; border-radius: 50%; background: #E5E7EB; flex-shrink: 0; position: relative; }
        .user-info h3 { font-size: 1rem; margin: 0; }
        .user-info span { font-size: 0.85rem; color: var(--text-light); }
        .post-content { margin-bottom: 15px; font-size: 1rem; }
        .post-image { width: 100%; height: 250px; background: linear-gradient(45deg, #CBD5E1, #94A3B8); border-radius: 8px; margin-bottom: 15px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 1.2rem; font-weight: bold;}
        .post-actions { display: flex; gap: 20px; border-top: 1px solid var(--border); padding-top: 15px; }
        .action-btn { display: flex; align-items: center; gap: 6px; color: var(--text-light); font-size: 0.9rem; cursor: pointer; }
        .action-btn:hover { color: var(--primary); }

        /* Sidebar */
        .sidebar { display: none; }
        @media (min-width: 1024px) {
            .sidebar { display: block; position: sticky; top: 80px; height: fit-content; }
        }
        .sidebar-card { background: var(--bg-card); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); margin-bottom: 20px; }
        .sidebar-title { font-size: 1.1rem; font-weight: 700; margin-bottom: 15px; }
        .trending-item { display: flex; justify-content: space-between; margin-bottom: 12px; cursor: pointer; }
        .trending-topic { font-weight: 500; }
        .trending-count { font-size: 0.85rem; color: var(--text-light); }

        /* Footer */
        .footer { background: var(--bg-card); border-top: 1px solid var(--border); padding: 40px 0; margin-top: 60px; }
        .footer-content { display: flex; flex-direction: column; gap: 20px; text-align: center; }
        .footer-links { display: flex; justify-content: center; gap: 20px; flex-wrap: wrap; }
        .copyright { color: var(--text-light); font-size: 0.9rem; }

        /* Forms */
        .form-group { margin-bottom: 20px; text-align: left; }
        .form-group label { display: block; margin-bottom: 8px; font-weight: 500; font-size: 0.95rem; }
        .form-control { width: 100%; padding: 12px; border: 1px solid var(--border); border-radius: 8px; font-size: 1rem; font-family: inherit; }
        .form-control:focus { outline: none; border-color: var(--primary); }
    </style>
</head>
